<?php
require_once __DIR__.'/../includes/database.php';require_once __DIR__.'/../includes/team-inventory.php';require_once __DIR__.'/../includes/pallet-activity.php';
function check_request($ok,$why){if(!$ok)throw new RuntimeException($why);}
function deny_request($fn,$status){try{$fn();}catch(CatalogException $e){check_request($e->status===$status,$e->getMessage());return;}throw new RuntimeException('Expected denial: '.$status);}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);initialize_database($db);initialize_database($db);
foreach(['Admin','Encargado','Operador','Propietario','Ajeno'] as $i=>$name)stock_query($db,'INSERT INTO users(name,public_name,email,password_hash) VALUES(?,?,?,?)',[$name,$name,'pending'.$i.'@example.invalid','unused']);
foreach([1,2] as $b)stock_query($db,"INSERT INTO stock_branches(owner_id,name,address,locality,province) VALUES(1,?,'A','B','C')",['Sucursal '.$b]);
stock_query($db,"INSERT INTO branch_workspaces(owner_id,name) VALUES(1,'Empresa')");stock_query($db,'INSERT INTO branch_workspace_locations(branch_id,workspace_id) VALUES(1,1),(2,1)');stock_query($db,"INSERT INTO branch_team_members(branch_id,user_id,role) VALUES(1,2,'manager'),(1,3,'operator')");team_select($db,3,1);
$label=stock_generate($db,4);$p=stock_claim($db,$label['code'],4);$id=$p['id'];stock_save_product($db,4,['pallet_id'=>$id,'ean'=>'96385074','name'=>'Takis','amount'=>50,'kind'=>'boxes','pack_size'=>14,'expires'=>'2030-01-01']);
