$r=team_pallet_request($db,$id,1);team_scan($db,3,$p['code'],1);check_request((int)stock_query($db,'SELECT COUNT(*) FROM notifications WHERE user_id=4')->fetchColumn()===1,'one owner notification on repeated scans');
check_request(!stock_detail($db,$p['code'],3)['can_edit'],'personal stock cannot use a pending team permission');deny_request(fn()=>stock_editable($db,$id,3),403);
$saved=team_request_edit($db,3,1,['action'=>'save_product','pallet_id'=>$id,'product_id'=>0,'ean'=>'96385074','name'=>'Takis','amount'=>1,'kind'=>'boxes','pack_size'=>14,'expires'=>'2030-01-01']);check_request((int)$saved['pallet']['products'][0]['units']===714,'pending adds exact package units');check_request((int)stock_detail($db,$p['code'],4)['products'][0]['units']===700,'confirmed stock isolated');
$list=team_inventory_page($db,2,1,'palets',[])['items'][0];check_request($list['pending_approval']&&(int)$list['units']===714&&(int)$list['original']['units']===700,'pallet original/proposal summary');
$goods=team_inventory_page($db,2,1,'mercaderia',[])['items'][0];check_request($goods['pending_approval']&&(int)$goods['units']===714,'pending included in team goods total');
$lots=team_inventory_page($db,2,1,'lotes',['ean'=>'96385074','expires'=>'2030-01-01'])['items'][0];check_request($lots['pending_delta']===14&&$lots['original_units']===700,'lot exact signed difference');
$movement=team_inventory_page($db,2,1,'movimientos',['action'=>'team_pending_edited'])['items'][0];check_request($movement['metadata']['old']===700&&$movement['metadata']['new']===714,'pending movement before/after');check_request(count(pallet_activity_list($db,3,$id)['items'])===1,'pending operator history restricted to own team proposals');
$prod=$saved['pallet']['products'][0];team_request_edit($db,2,1,['action'=>'deduct_product','pallet_id'=>$id,'product_id'=>$prod['id'],'revision'=>$prod['revision'],'amount'=>2,'kind'=>'units']);$detail=team_request_detail($db,$p['code'],3,1);check_request((int)$detail['products'][0]['units']===712,'supervisor can review operator draft');
deny_request(fn()=>team_request_edit($db,5,1,['action'=>'delete_product','pallet_id'=>$id]),403);deny_request(fn()=>team_request_edit($db,3,1,['action'=>'description','pallet_id'=>$id]),403);deny_request(fn()=>team_request_resolve($db,3,$r['id'],'accepted',$detail['team_request']['revision']),403);deny_request(fn()=>team_request_resolve($db,4,$r['id'],'accepted',1),409);
$db->beginTransaction();team_request_resolve($db,4,$r['id'],'accepted',$detail['team_request']['revision']);$db->commit();check_request(stock_query($db,'SELECT read_at FROM notifications WHERE user_id=4 AND event_key=?',['team-pallet-request:'.$r['id']])->fetchColumn()!==null,'Owner resolution reads its notification');$confirmed=stock_detail($db,$p['code'],4);check_request((int)$confirmed['branch_id']===1&&(int)$confirmed['products'][0]['units']===712,'approval applies once');deny_request(fn()=>team_request_resolve($db,4,$r['id'],'accepted',$detail['team_request']['revision']),409);check_request(team_request_edit($db,3,1,['pallet_id'=>$id,'action'=>'save_product'])===null,'same branch uses normal operations');check_request(stock_editable($db,$id,3)['id']==$id,'accepted team normal server access');
// Another team gets a proposal, never overwrites the current branch or stock.
team_select($db,1,2);$foreign=team_scan($db,1,$p['code'],2);check_request($foreign['pending_approval']&&(int)stock_detail($db,$p['code'],4)['branch_id']===1,'foreign branch cannot invade');$r2=team_pallet_request($db,$id,2);team_request_resolve($db,1,$r2['id'],'cancelled',$r2['revision']);check_request(team_inventory_page($db,1,2,'palets',[])['items']===[],'cancel removes proposal only');check_request((int)stock_detail($db,$p['code'],4)['products'][0]['units']===712,'cancel preserves original');
// Reject a no-branch request and detect owner edits before approval.
stock_query($db,'UPDATE pallets SET branch_id=NULL WHERE id=?',[$id]);team_select($db,3,1);team_scan($db,3,$p['code'],1);$r=team_pallet_request($db,$id,1);stock_touch($db,$id,4);deny_request(fn()=>team_request_resolve($db,4,$r['id'],'accepted',$r['revision']),409);team_request_resolve($db,4,$r['id'],'rejected',$r['revision']);check_request(stock_query($db,'SELECT read_at FROM notifications WHERE user_id=4 AND event_key=?',['team-pallet-request:'.$r['id']])->fetchColumn()!==null,'Discard reads its notification');check_request(stock_detail($db,$p['code'],4)['branch_id']===null,'reject never assigns branch');
team_scan($db,3,$p['code'],1);$r=team_pallet_request($db,$id,1);$v=team_request_detail($db,$p['code'],3,1)['products'][0];team_request_edit($db,3,1,['action'=>'delete_product','pallet_id'=>$id,'product_id'=>$v['id'],'revision'=>$v['revision']]);$lot=team_inventory_page($db,2,1,'lotes',['ean'=>'96385074','expires'=>'2030-01-01'])['items'][0];check_request((int)$lot['units']===0&&$lot['pending_delta']===-712,'full removal remains visible as pending negative');
stock_query($db,'UPDATE branch_team_members SET expires_at=? WHERE user_id=3',[time()-1]);deny_request(fn()=>team_request_detail($db,$p['code'],3,1),403);
team_require_position($db,1,[]);check_request(team_security($db,1)['enabled']===0,'GPS disabled regardless of previous setting');
echo "OK: isolated proposals, exact units/dates, owner approval/rejection/conflicts, scope, expiry, cancellation, team projection and no GPS.\n";
